import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../core/providers.dart';
import '../../data/repositories/machines_repository.dart';
import '../../domain/models/machine_summary.dart';
import '../../domain/models/network_settings.dart';

class NetworkSettingsScreen extends ConsumerStatefulWidget {
  const NetworkSettingsScreen({super.key});

  @override
  ConsumerState<NetworkSettingsScreen> createState() =>
      _NetworkSettingsScreenState();
}

class _NetworkSettingsScreenState extends ConsumerState<NetworkSettingsScreen> {
  final _wifiSsid = TextEditingController();
  final _wifiPass = TextEditingController();
  final _gsmApn = TextEditingController();
  final _gsmUser = TextEditingController();
  final _gsmPass = TextEditingController();
  final _apiHost = TextEditingController();
  final _apiPort = TextEditingController();
  final _apiPath = TextEditingController();
  final _deviceKey = TextEditingController();

  bool _loading = true;
  bool _saving = false;
  bool _loadingDevices = false;
  bool _creatingDevice = false;
  bool _useCustomApi = false;
  String _linkMode = 'wifi';

  List<MachineSummary> _machines = const [];
  List<MachineDeviceInfo> _devices = const [];
  String? _selectedMachineId;
  String? _selectedDeviceId;

  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void dispose() {
    _wifiSsid.dispose();
    _wifiPass.dispose();
    _gsmApn.dispose();
    _gsmUser.dispose();
    _gsmPass.dispose();
    _apiHost.dispose();
    _apiPort.dispose();
    _apiPath.dispose();
    _deviceKey.dispose();
    super.dispose();
  }

  Future<void> _load() async {
    setState(() => _loading = true);
    try {
      final settings = await ref.read(networkSettingsRepositoryProvider).load();
      final machines = await ref.read(machinesRepositoryProvider).listMachines();
      if (!mounted) return;

      final machineIds = machines.map((m) => m.id).toSet();
      var selectedMachineId = settings.selectedMachineId;
      if (selectedMachineId == null || !machineIds.contains(selectedMachineId)) {
        selectedMachineId = machines.isNotEmpty ? machines.first.id : null;
      }

      _applySettings(settings);
      setState(() {
        _machines = machines;
        _selectedMachineId = selectedMachineId;
        _selectedDeviceId = settings.selectedDeviceId;
        _deviceKey.text = settings.deviceKey;
        _loading = false;
      });

      if (selectedMachineId != null) {
        await _loadDevices(selectedMachineId, preferDeviceId: settings.selectedDeviceId);
      }
    } catch (e) {
      if (!mounted) return;
      setState(() => _loading = false);
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Не удалось загрузить: $e')),
      );
    }
  }

  void _applySettings(NetworkSettings s) {
    _wifiSsid.text = s.wifiSsid;
    _wifiPass.text = s.wifiPassword;
    _gsmApn.text = s.gsmApn;
    _gsmUser.text = s.gsmUser;
    _gsmPass.text = s.gsmPassword;
    _apiHost.text = s.apiHost;
    _apiPort.text = '${s.apiPort}';
    _apiPath.text = s.apiPath;
    _linkMode = s.linkMode == 'gsm' ? 'gsm' : 'wifi';
    _useCustomApi = !s.isDefaultApi;
  }

  Future<void> _loadDevices(
    String machineId, {
    String? preferDeviceId,
  }) async {
    setState(() => _loadingDevices = true);
    try {
      final devices =
          await ref.read(machinesRepositoryProvider).listMachineDevices(machineId);
      if (!mounted) return;
      final ids = devices.map((d) => d.deviceId).toSet();
      var selected = preferDeviceId ?? _selectedDeviceId;
      if (selected == null || !ids.contains(selected)) {
        selected = devices.isNotEmpty ? devices.first.deviceId : null;
      }
      setState(() {
        _devices = devices;
        _selectedDeviceId = selected;
        _loadingDevices = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _devices = const [];
        _selectedDeviceId = null;
        _loadingDevices = false;
      });
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            'Устройства не загрузились ($e). '
            'Можно ввести device_id и ключ вручную.',
          ),
        ),
      );
    }
  }

  NetworkSettings _buildSettings() {
    final port = int.tryParse(_apiPort.text.trim()) ?? NetworkSettings.defaultApiPort;
    final path = _apiPath.text.trim().isEmpty ? '/v1' : _apiPath.text.trim();
    return NetworkSettings(
      wifiSsid: _wifiSsid.text.trim(),
      wifiPassword: _wifiPass.text,
      gsmApn: _gsmApn.text.trim(),
      gsmUser: _gsmUser.text.trim(),
      gsmPassword: _gsmPass.text,
      apiHost: _useCustomApi
          ? _apiHost.text.trim()
          : NetworkSettings.defaultApiHost,
      apiPort: _useCustomApi ? port : NetworkSettings.defaultApiPort,
      apiPath: _useCustomApi ? path : NetworkSettings.defaultApiPath,
      linkMode: _linkMode,
      selectedMachineId: _selectedMachineId ?? '',
      selectedDeviceId: _selectedDeviceId ?? '',
      deviceKey: _deviceKey.text.trim(),
    );
  }

  MachineSummary? get _selectedMachine {
    final id = _selectedMachineId;
    if (id == null) return null;
    for (final m in _machines) {
      if (m.id == id) return m;
    }
    return null;
  }

  Future<void> _onMachineChanged(String? machineId) async {
    if (machineId == null) return;
    setState(() {
      _selectedMachineId = machineId;
      _selectedDeviceId = null;
      _devices = const [];
      _deviceKey.clear();
    });
    await _loadDevices(machineId);
  }

  Future<void> _createDevice() async {
    final machine = _selectedMachine;
    if (machine == null) return;

    final nameCtrl = TextEditingController(
      text: 'ESP32 ${_devices.length + 1}',
    );
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Новый ключ платы'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              'Для «${machine.name}». Ключ покажется один раз — '
              'скопируйте команды сразу после создания.',
              style: Theme.of(ctx).textTheme.bodySmall,
            ),
            const SizedBox(height: 12),
            TextField(
              controller: nameCtrl,
              decoration: const InputDecoration(
                labelText: 'Имя устройства',
                border: OutlineInputBorder(),
              ),
            ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: const Text('Отмена'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('Создать'),
          ),
        ],
      ),
    );
    if (ok != true || !mounted) return;

    setState(() => _creatingDevice = true);
    try {
      final created = await ref.read(machinesRepositoryProvider).createMachineDevice(
            machineId: machine.id,
            name: nameCtrl.text.trim().isEmpty
                ? 'ESP32 ${_devices.length + 1}'
                : nameCtrl.text.trim(),
          );
      if (!mounted) return;
      setState(() {
        _devices = [..._devices, created];
        _selectedDeviceId = created.deviceId;
        _deviceKey.text = created.deviceKey ?? '';
        _creatingDevice = false;
      });
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Ключ создан. Нажмите «Скопировать команды» и вставьте в Serial.',
          ),
        ),
      );
    } catch (e) {
      if (!mounted) return;
      setState(() => _creatingDevice = false);
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Не удалось создать устройство: $e')),
      );
    } finally {
      nameCtrl.dispose();
    }
  }

  Future<void> _save() async {
    setState(() => _saving = true);
    try {
      final s = _buildSettings();
      await ref.read(networkSettingsRepositoryProvider).save(s);
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Сохранено в приложении')),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Ошибка сохранения: $e')),
      );
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  Future<void> _copyUsbCommands() async {
    final s = _buildSettings();
    if (s.selectedMachineId.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Выберите станцию (машину)')),
      );
      return;
    }
    if (s.selectedDeviceId.isEmpty || s.deviceKey.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Нужны device_id и ключ: создайте новый ключ или вставьте сохранённый.',
          ),
        ),
      );
      return;
    }
    if (s.linkMode == 'wifi' && s.wifiSsid.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Укажите SSID Wi‑Fi')),
      );
      return;
    }

    await ref.read(networkSettingsRepositoryProvider).save(s);
    final text = s.toBlockUsbCommands();
    await Clipboard.setData(ClipboardData(text: text));
    if (!mounted) return;

    final machine = _selectedMachine;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          'Команды для «${machine?.name ?? 'машины'}» скопированы. '
          'Вставьте в Serial Monitor ESP32 (115200):\n$text',
        ),
        duration: const Duration(seconds: 14),
      ),
    );
    await showDialog<void>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text('Прошивка: ${machine?.name ?? 'машина'}'),
        content: SingleChildScrollView(
          child: SelectableText(
            'Подключите нужную плату по USB и вставьте:\n\n$text\n\n'
            'MACHINE_ID и KEY привязаны к выбранной станции.\n'
            'CFG сохраняет всё в NVS платы.\n\n'
            'Если в мониторе ещё старый Wi‑Fi — команды не были вставлены '
            'после смены SSID.',
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx),
            child: const Text('Понятно'),
          ),
        ],
      ),
    );
  }

  Future<void> _resetDefaults() async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Сбросить сеть?'),
        content: const Text(
          'Wi‑Fi / GSM / API вернутся к значениям по умолчанию. '
          'Выбранная машина и ключ не трогаются.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: const Text('Отмена'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('Сбросить'),
          ),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    final cur = _buildSettings();
    _applySettings(
      NetworkSettings.defaults.copyWith(
        selectedMachineId: cur.selectedMachineId,
        selectedDeviceId: cur.selectedDeviceId,
        deviceKey: cur.deviceKey,
      ),
    );
    setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return Scaffold(
      appBar: AppBar(
        title: const Text('Настройка блока и сети'),
        actions: [
          IconButton(
            tooltip: 'Сбросить сеть',
            onPressed: _loading || _saving ? null : _resetDefaults,
            icon: const Icon(Icons.restart_alt),
          ),
        ],
      ),
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : ListView(
              padding: const EdgeInsets.fromLTRB(16, 12, 16, 28),
              children: [
                Text(
                  'Одна плата = одна станция. Выберите машину, создайте/вставьте '
                  'ключ, затем скопируйте команды в Serial этой платы.',
                  style: theme.textTheme.bodyMedium?.copyWith(
                    color: theme.colorScheme.onSurfaceVariant,
                  ),
                ),
                const SizedBox(height: 16),
                Text('Станция (MACHINE_ID)', style: theme.textTheme.titleMedium),
                const SizedBox(height: 8),
                if (_machines.isEmpty)
                  Card(
                    child: Padding(
                      padding: const EdgeInsets.all(12),
                      child: Text(
                        'Нет машин в аккаунте. Создайте станцию на экране машин.',
                        style: theme.textTheme.bodyMedium,
                      ),
                    ),
                  )
                else
                  DropdownButtonFormField<String>(
                    // ignore: deprecated_member_use
                    value: _selectedMachineId,
                    decoration: const InputDecoration(
                      border: OutlineInputBorder(),
                      labelText: 'Машина',
                    ),
                    items: [
                      for (final m in _machines)
                        DropdownMenuItem(
                          value: m.id,
                          child: Text('${m.name} (${m.code})'),
                        ),
                    ],
                    onChanged: _saving ? null : _onMachineChanged,
                  ),
                if (_selectedMachine != null) ...[
                  const SizedBox(height: 8),
                  SelectableText(
                    'MACHINE_ID: ${_selectedMachine!.id}',
                    style: theme.textTheme.bodySmall?.copyWith(
                      fontFamily: 'monospace',
                      color: theme.colorScheme.onSurfaceVariant,
                    ),
                  ),
                ],
                const SizedBox(height: 16),
                Row(
                  children: [
                    Expanded(
                      child: Text(
                        'Плата / ключ (X-Device-Key)',
                        style: theme.textTheme.titleMedium,
                      ),
                    ),
                    FilledButton.tonalIcon(
                      onPressed: _saving ||
                              _creatingDevice ||
                              _selectedMachineId == null
                          ? null
                          : _createDevice,
                      icon: _creatingDevice
                          ? const SizedBox(
                              width: 16,
                              height: 16,
                              child: CircularProgressIndicator(strokeWidth: 2),
                            )
                          : const Icon(Icons.add),
                      label: const Text('Новый ключ'),
                    ),
                  ],
                ),
                const SizedBox(height: 8),
                if (_loadingDevices)
                  const Padding(
                    padding: EdgeInsets.symmetric(vertical: 8),
                    child: LinearProgressIndicator(),
                  )
                else if (_devices.isNotEmpty)
                  DropdownButtonFormField<String>(
                    // ignore: deprecated_member_use
                    value: _selectedDeviceId,
                    decoration: const InputDecoration(
                      border: OutlineInputBorder(),
                      labelText: 'Устройство',
                    ),
                    items: [
                      for (final d in _devices)
                        DropdownMenuItem(
                          value: d.deviceId,
                          child: Text(
                            '${d.name.isEmpty ? d.deviceId : d.name}'
                            '${d.lastSeenAt == null ? ' · новый' : ''}',
                          ),
                        ),
                    ],
                    onChanged: _saving
                        ? null
                        : (id) {
                            setState(() => _selectedDeviceId = id);
                            final match = _devices
                                .where((d) => d.deviceId == id)
                                .toList();
                            if (match.isNotEmpty &&
                                match.first.deviceKey != null &&
                                match.first.deviceKey!.isNotEmpty) {
                              _deviceKey.text = match.first.deviceKey!;
                            }
                          },
                  )
                else
                  Text(
                    'Устройств пока нет — создайте ключ кнопкой выше '
                    'или введите device_id вручную.',
                    style: theme.textTheme.bodySmall?.copyWith(
                      color: theme.colorScheme.onSurfaceVariant,
                    ),
                  ),
                const SizedBox(height: 10),
                TextFormField(
                  initialValue: _selectedDeviceId ?? '',
                  decoration: const InputDecoration(
                    labelText: 'device_id (DEVICE …)',
                    border: OutlineInputBorder(),
                    helperText: 'Можно вставить вручную, если ключ уже был создан',
                  ),
                  onChanged: (v) => setState(() {
                    _selectedDeviceId = v.trim().isEmpty ? null : v.trim();
                  }),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: _deviceKey,
                  obscureText: true,
                  decoration: const InputDecoration(
                    labelText: 'device_key (KEY …)',
                    border: OutlineInputBorder(),
                    helperText:
                        'API не отдаёт старый ключ повторно — только при создании',
                  ),
                ),
                const SizedBox(height: 20),
                Text('Режим связи', style: theme.textTheme.titleMedium),
                const SizedBox(height: 4),
                SegmentedButton<String>(
                  segments: const [
                    ButtonSegment(
                      value: 'wifi',
                      label: Text('Wi‑Fi'),
                      icon: Icon(Icons.wifi),
                    ),
                    ButtonSegment(
                      value: 'gsm',
                      label: Text('GSM (SIM)'),
                      icon: Icon(Icons.cell_tower),
                    ),
                  ],
                  selected: {_linkMode},
                  onSelectionChanged: (s) {
                    if (s.isEmpty) return;
                    setState(() => _linkMode = s.first);
                  },
                ),
                const SizedBox(height: 8),
                Text(
                  _linkMode == 'wifi'
                      ? 'Блок в зоне Wi‑Fi объекта.'
                      : 'Блок без Wi‑Fi — SIM900A + SIM.',
                  style: theme.textTheme.bodySmall?.copyWith(
                    color: theme.colorScheme.onSurfaceVariant,
                  ),
                ),
                const SizedBox(height: 20),
                Text('Wi‑Fi на объекте', style: theme.textTheme.titleMedium),
                const SizedBox(height: 8),
                TextField(
                  controller: _wifiSsid,
                  decoration: const InputDecoration(
                    labelText: 'SSID сети',
                    border: OutlineInputBorder(),
                  ),
                  textInputAction: TextInputAction.next,
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: _wifiPass,
                  obscureText: true,
                  decoration: const InputDecoration(
                    labelText: 'Пароль Wi‑Fi',
                    border: OutlineInputBorder(),
                  ),
                ),
                const SizedBox(height: 20),
                Text('GSM / APN (SIM)', style: theme.textTheme.titleMedium),
                const SizedBox(height: 8),
                TextField(
                  controller: _gsmApn,
                  decoration: const InputDecoration(
                    labelText: 'APN',
                    hintText: 'internet.mts.ru',
                    border: OutlineInputBorder(),
                  ),
                  textInputAction: TextInputAction.next,
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: _gsmUser,
                  decoration: const InputDecoration(
                    labelText: 'Пользователь APN',
                    border: OutlineInputBorder(),
                  ),
                  textInputAction: TextInputAction.next,
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: _gsmPass,
                  obscureText: true,
                  decoration: const InputDecoration(
                    labelText: 'Пароль APN',
                    border: OutlineInputBorder(),
                  ),
                ),
                const SizedBox(height: 20),
                Text('Сервер API', style: theme.textTheme.titleMedium),
                const SizedBox(height: 4),
                Text(
                  'По умолчанию: ${NetworkSettings.defaults.apiBaseUrl}',
                  style: theme.textTheme.bodySmall?.copyWith(
                    color: theme.colorScheme.onSurfaceVariant,
                  ),
                ),
                SwitchListTile(
                  contentPadding: EdgeInsets.zero,
                  title: const Text('Другой сервер'),
                  subtitle: const Text('Только если меняете IP / порт / путь'),
                  value: _useCustomApi,
                  onChanged: (v) {
                    setState(() {
                      _useCustomApi = v;
                      if (!v) {
                        _apiHost.text = NetworkSettings.defaultApiHost;
                        _apiPort.text = '${NetworkSettings.defaultApiPort}';
                        _apiPath.text = NetworkSettings.defaultApiPath;
                      }
                    });
                  },
                ),
                if (_useCustomApi) ...[
                  TextField(
                    controller: _apiHost,
                    decoration: const InputDecoration(
                      labelText: 'Хост / IP',
                      border: OutlineInputBorder(),
                    ),
                  ),
                  const SizedBox(height: 10),
                  TextField(
                    controller: _apiPort,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(
                      labelText: 'Порт',
                      border: OutlineInputBorder(),
                    ),
                  ),
                  const SizedBox(height: 10),
                  TextField(
                    controller: _apiPath,
                    decoration: const InputDecoration(
                      labelText: 'Путь (обычно /v1)',
                      border: OutlineInputBorder(),
                    ),
                  ),
                ],
                const SizedBox(height: 24),
                FilledButton.icon(
                  onPressed: _saving ? null : _copyUsbCommands,
                  icon: const Icon(Icons.copy_all),
                  label: const Text('Скопировать команды для этой платы'),
                ),
                const SizedBox(height: 10),
                OutlinedButton.icon(
                  onPressed: _saving ? null : _save,
                  icon: _saving
                      ? const SizedBox(
                          width: 18,
                          height: 18,
                          child: CircularProgressIndicator(strokeWidth: 2),
                        )
                      : const Icon(Icons.save_outlined),
                  label: Text(_saving ? 'Сохранение…' : 'Сохранить в приложении'),
                ),
                const SizedBox(height: 12),
                Text(
                  'В мониторе порта видно NVS платы. Пока не вставите новые '
                  'команды + CFG, там останется старый Wi‑Fi (например R2D2).',
                  style: theme.textTheme.bodySmall?.copyWith(
                    color: theme.colorScheme.onSurfaceVariant,
                  ),
                ),
              ],
            ),
    );
  }
}
